inline unsigned Digit(char c){return unsigned(c<='9'?c-'0':c-'a'+10);}
inline unsigned Byte(const char* p){return Digit(p[0])*16+Digit(p[1]);}
inline unsigned Pixel(int kind,int x,int y){const char* p=Cells[kind]+8*(y*Width+x);return (Byte(p+6)<<24)|(Byte(p)<<16)|(Byte(p+2)<<8)|Byte(p+4);}
